'use client'

import { useEffect, useState } from "react";
import { clearAccessToken, getAccessToken, setAccessToken } from "../accessTokenStore";
import { useUserContext } from "../UserContext";

// apiFetch.ts
export async function apiFetch(url: string, options: RequestInit = {}) {
  // Access token stored in memory (React state or module-level variable)
  const token = getAccessToken(); // just in-memory, no SecureStore

  let res = await fetch(url, {
    ...options,
    headers: {
      ...(options.headers || {}),
      Authorization: `Bearer ${token}`
    },
    credentials: "include", // ensures cookies are sent (refresh token)
  });

  if (res.status !== 401) return res;

  // Access token expired → attempt refresh
  try {
    const refreshRes = await fetch("/auth/refresh", {
      method: "POST",
      credentials: "include", // send HttpOnly refresh cookie
    });

    if (!refreshRes.ok) {
      clearAccessToken(); // refresh failed → logout
      window.location.href="/"
      return;
    }

    const { accessToken: newAccessToken } = await refreshRes.json();
    setAccessToken(newAccessToken); // update in-memory token

    // Retry original request with new token
    res = await fetch(url, {
      ...options,
      headers: {
        ...(options.headers || {}),
        Authorization: `Bearer ${newAccessToken}`,
      },
      credentials: "include",
    });

    if (res.status === 401) {
      clearAccessToken();
      return;
    }

    return res;
  } catch (err) {
    clearAccessToken();
    console.error(err);
  }
}



export const useGetUser = () => {
  const { user, updateUser } = useUserContext();
  const [loading, setLoading] = useState(!user);
  const [error, setError] = useState(null);
  const getUser = async () => {
    // 1️⃣ Check global state
    if (user) return user;

    const accessToken = getAccessToken()
    if (!accessToken) {
      return null;
    }
  

    // 2️⃣ Check AsyncStorage
    try {
      const storedJSON = localStorage.getItem('user-data');
      if (storedJSON) {
        const storedUser = JSON.parse(storedJSON);
        updateUser(storedUser);
        return storedUser;
      }
    } catch (err) {
      console.error('Failed to read or parse user from AsyncStorage', err);
      localStorage.removeItem('user-data'); // clear corrupted data
    }

    // 3️⃣ Fetch from API (using apiFetch to auto-refresh token)
    try {
       
      const res = await apiFetch(`${process.env.API_URL}/user/simple`);
      if (res.status === 401){
        return
      }
      if (!res.ok) throw new Error(`Fetch failed: ${res.status}`);

      const userData = await res.json();
      const userJSON = JSON.stringify(userData);

      // Update AsyncStorage and global state
      localStorage.setItem('user-data', userJSON);
      updateUser(userData);

      return userData;
    } catch (err) {
      return

    }
  };

  useEffect(() => {
    const fetchUser = async () => {
      if (!user) {
        setLoading(true);
        try {
          await getUser();
        } catch (err) {
          setError(err);
        } finally {
          setLoading(false);
        }
      }
    };

    fetchUser();
  }, [user]);

  return { user, loading, error, refetch:getUser, updateUser };
};
